/**
 * A `.blend` in import mode: Blender itself converts it, here, in the tab.
 *
 * A `.blend` holds a recipe only Blender evaluates, so the converter for it
 * is Blender, compiled to WebAssembly and served beside the app
 * (`blender-runtime/`, put there by a build that asked for it). Its threaded
 * build needs a cross-origin isolated page, and an isolated page cannot open
 * worlds from hosts that do not allow embedding, so the isolation lasts
 * exactly as long as the conversion: the file is stashed, the page reloads
 * itself at the address the import server isolates, Blender boots in a
 * worker (a one-time download the browser keeps), runs the same export
 * script the command line runs, the result is staged, and the page reloads
 * itself back to its ordinary self, where the world opens like any import.
 *
 * The runtime is a separate program, loaded from its own files by address
 * and spoken to by messages; nothing of it is bundled here.
 */
import { buildWorld, type BuiltWorld } from '@fivesqd/ingest/browser';
import exportScript from '@fivesqd/ingest/blend_export.py?raw';
import { blenderOutputs, BLENDER_OUT_GLB, BLENDER_OUT_REPORT } from './blendOutputs';
import { stageReporter, type BlendStage } from './blendStages';
import type { ImportFile } from './importFiles';
import { ensureImportServer } from './importServer';
import { newWorldRoom, presentStaged, showStage, stageBuilt, type ImportDeps, type StageAction } from './importMode';
import { summarizeImport } from './importSummary';
import { handBackUrl, isolatedUrl } from './isolation';
import { stashOpenedWorld, stashPendingImport, takeOpenedWorld, takePendingImport } from './pendingImport';

/** The runtime loader's surface, as its files export it. */
interface BootProgress {
  phase: 'download' | 'compile' | 'start' | 'ready';
  fraction: number;
  loaded: number;
  total: number;
  detail: string;
}
interface BlenderRunner {
  run(job: { code: string; blendFile?: string; files: Record<string, Uint8Array>; onLine?: (line: string) => void }): Promise<{ output: string; files: Record<string, Uint8Array> }>;
}
interface RuntimeLoader {
  createBlenderRunner(options: { runtimeUrl: string; threads?: boolean | 'auto'; onProgress?: (p: BootProgress) => void }): BlenderRunner;
}

export const RUNTIME_DIR = 'blender-runtime/';
const LOADER = `${RUNTIME_DIR}loader/browser/index.js`;
/** Bake size and samples for an import: smaller than the command line's defaults, for time. */
const BAKE_RESOLUTION = 512;
const BAKE_SAMPLES = 2;

const NOT_ENABLED =
  'Blender in the browser is not enabled on this WebVerse. ' +
  "Convert the .blend with Blender's add-on (Save and Publish) or with veml-ingest on a computer with Blender.";

/** The window's isolation flag, read where the DOM library does not type it. */
const isIsolated = (win: Window): boolean => Boolean((win as Window & { crossOriginIsolated?: boolean }).crossOriginIsolated);

const close = (doc: Document) => ({ label: 'Close', run: () => showStage(doc, 'closed') });

/** Is the runtime served beside the app? A build ships it only when asked. */
async function runtimeAvailable(doc: Document): Promise<boolean> {
  try {
    // A GET of the small manifest, not a HEAD: a plain static server may not answer HEAD cleanly.
    const res = await fetch(new URL(`${RUNTIME_DIR}manifest.json`, doc.baseURI).href, { cache: 'no-store' });
    return res.ok;
  } catch {
    return false;
  }
}

/** Entry from the import stage: convert here if the page is isolated, otherwise reload isolated with the file kept. */
export async function importBlend(doc: Document, model: ImportFile, sidecars: ReadonlyMap<string, Uint8Array>, deps: ImportDeps): Promise<void> {
  const win = doc.defaultView!;
  if (!(await runtimeAvailable(doc))) {
    showStage(doc, 'failed', `Cannot open ${model.name} here`, [NOT_ENABLED], [close(doc)]);
    return;
  }
  if (isIsolated(win)) {
    await convertBlend(doc, model, sidecars, deps, null);
    return;
  }
  showStage(doc, 'converting', `Opening ${model.name}`, ['Blender runs here, in your browser. The page reloads once to make room for it, and once more when it is done; nothing is uploaded.']);
  try {
    const server = await ensureImportServer(win);
    await stashPendingImport(server.store, server.scopeUrl, model, sidecars);
  } catch (err) {
    showStage(doc, 'failed', `Could not open ${model.name}`, [err instanceof Error ? err.message : String(err)], [close(doc)]);
    return;
  }
  win.location.replace(isolatedUrl(win.location.href));
}

/** Entry on boot of an isolated page: the kept file, if any, is converted now. */
export async function resumePendingImport(doc: Document, deps: ImportDeps): Promise<void> {
  const win = doc.defaultView!;
  const server = await ensureImportServer(win);
  const pending = await takePendingImport(server.store, server.scopeUrl);
  if (!pending) return;
  if (!isIsolated(win)) {
    showStage(doc, 'failed', `Could not open ${pending.model.name}`, ['The page could not be isolated for Blender in this browser. ' + NOT_ENABLED], [close(doc)]);
    return;
  }
  await convertBlend(doc, pending.model, pending.sidecars, deps, null).catch(() => false);
}

/**
 * Converts in a window opened only for that (blendWindow.ts), which must
 * already be isolated, and leaves the world staged in this origin's store.
 * True once it is staged. A failure stays on the card, with `leave` as the
 * one thing to press: there is no page behind the card to go back to.
 * `watch` is told each stage; `hear` each line Blender says.
 */
export async function convertInWindow(
  doc: Document,
  model: ImportFile,
  sidecars: ReadonlyMap<string, Uint8Array>,
  deps: ImportDeps,
  leave: StageAction,
  watch?: BlendWatch,
  hear?: (line: string) => void,
): Promise<boolean> {
  if (!(await runtimeAvailable(doc))) {
    watch?.({ stage: 'failed', why: 'Blender is not served beside this page' });
    showStage(doc, 'failed', `Cannot open ${model.name} here`, [NOT_ENABLED], [leave]);
    return false;
  }
  if (!isIsolated(doc.defaultView!)) {
    watch?.({ stage: 'failed', why: 'the window is not isolated' });
    showStage(doc, 'failed', `Could not open ${model.name}`, ['The window could not be isolated for Blender in this browser. ' + NOT_ENABLED], [leave]);
    return false;
  }
  return convertBlend(doc, model, sidecars, deps, leave, watch, hear).catch((err: unknown) => {
    watch?.({ stage: 'failed', why: err instanceof Error ? err.message : String(err) });
    return false;
  });
}

/**
 * Told each stage of a conversion as it is reached, beside what the card
 * shows: loading Blender (with how much, once that is known), starting it,
 * converting, or that it failed and why in a line.
 */
export type BlendWatch = (at: { stage: 'loading' | 'starting' | 'converting' | 'converted' | 'staging'; percent?: number } | { stage: 'failed'; why: string }) => void;

/** Entry on boot of the ordinary page the isolated one handed back to: the converted world, if any, opens now. */
export async function resumeOpenedWorld(doc: Document, deps: ImportDeps): Promise<void> {
  const win = doc.defaultView!;
  const server = await ensureImportServer(win);
  const opened = await takeOpenedWorld(server.store, server.scopeUrl);
  if (!opened) return;
  await presentStaged(doc, { ...opened, bytesOf: (url) => server.store.get(url) }, deps);
}

/**
 * Converts and stages the world; true once it is staged. On a failure the
 * card says why and stays. `leave`: null on the client's own page, which
 * reloads itself plain and opens the world; in a window opened only to
 * convert, the one action its cards offer, and the world is left staged.
 */
async function convertBlend(
  doc: Document,
  model: ImportFile,
  sidecars: ReadonlyMap<string, Uint8Array>,
  deps: ImportDeps,
  leave: StageAction | null,
  watch?: BlendWatch,
  hear?: (line: string) => void,
): Promise<boolean> {
  const win = doc.defaultView!;
  const done = leave ?? close(doc);
  const title = model.name.replace(/\.blend$/i, '');
  const say = (lines: string[]): void => showStage(doc, 'converting', `Opening ${model.name}`, lines);
  // Whoever is watching always sees which of the three steps this is, and is told when nothing has moved for a
  // while (blendStages.ts). The first load of Blender is the long one, and looked stuck with no number on it.
  const shown = stageReporter(say, {
    now: () => Date.now(),
    every: (ms, run) => {
      const timer = win.setInterval(run, ms);
      return () => win.clearInterval(timer);
    },
  });
  // Each stage goes to the card and to whoever is watching the work from outside it.
  const report = {
    set(stage: BlendStage): void {
      shown.set(stage);
      if (stage.step === 'loading') watch?.({ stage: 'loading', ...(stage.loaded !== undefined && stage.total ? { percent: Math.round((100 * stage.loaded) / stage.total) } : {}) });
      else watch?.({ stage: stage.step === 'converting' ? 'converting' : 'starting' });
    },
    stop: (): void => shown.stop(),
  };
  /** The work is over without a world: say why, and stop counting. */
  const failed = (heading: string, lines: string[]): false => {
    report.stop();
    watch?.({ stage: 'failed', why: `${heading}: ${lines.join(' ')}` });
    showStage(doc, 'failed', heading, lines, [done]);
    return false;
  };
  report.set({ step: 'loading' });
  let runner: BlenderRunner;
  try {
    const loader = (await import(/* @vite-ignore */ new URL(LOADER, doc.baseURI).href)) as RuntimeLoader;
    runner = loader.createBlenderRunner({
      runtimeUrl: new URL(RUNTIME_DIR, doc.baseURI).href,
      threads: true,
      onProgress: (p) => {
        if (p.phase === 'download') report.set({ step: 'loading', loaded: p.loaded, total: p.total });
        else if (p.phase === 'compile') report.set({ step: 'preparing' });
        else report.set({ step: 'starting' });
      },
    });
  } catch (err) {
    return failed(`Could not open ${model.name}`, [`Blender could not be loaded: ${err instanceof Error ? err.message : String(err)}`]);
  }

  const files: Record<string, Uint8Array> = { '/in/scene.blend': model.bytes, '/in/blend_export.py': new TextEncoder().encode(exportScript) };
  for (const [name, bytes] of sidecars) files[`/in/${name}`] = bytes;
  const code = [
    'import sys',
    `sys.argv = ['blender', '--', '/in/scene.blend', '${BLENDER_OUT_GLB}', '${BLENDER_OUT_REPORT}', '${BAKE_RESOLUTION}', '${BAKE_SAMPLES}', '', 'JPEG']`,
    'exec(compile(open("/in/blend_export.py").read(), "/in/blend_export.py", "exec"))',
  ].join('\n');
  const tail: string[] = [];
  let result: { output: string; files: Record<string, Uint8Array> };
  try {
    result = await runner.run({
      code,
      blendFile: '/in/scene.blend',
      files,
      onLine: (line) => {
        // Every line, as it came, to whoever keeps an account of the work; the card shows fewer.
        hear?.(line);
        // Blender's own progress lines, not Python's warnings about the script.
        if (!/\S/.test(line) || /Warning|warning:|^\s|Traceback/.test(line)) return;
        tail.push(line.replace(/^\d\d:\d\d:\d\d \| /, '').trim());
        if (tail.length > 6) tail.shift();
        report.set({ step: 'converting', file: model.name, tail: [...tail] });
      },
    });
  } catch (err) {
    const e = err as Error & { output?: string };
    return failed(`Blender could not convert ${model.name}`, [e.message, ...(e.output ? e.output.split('\n').slice(-6) : [])]);
  }
  report.stop();
  // Blender is done; what follows is this page's own work, and a window that stops now says so by this stage.
  watch?.({ stage: 'converted' });

  let built: BuiltWorld;
  try {
    const converted = blenderOutputs(result.files);
    built = await buildWorld({ name: model.name, bytes: model.bytes, files: sidecars, converted }, { toolVersion: 'webverse', title, forceMaterialDefaults: true, ...(await newWorldRoom()) });
  } catch (err) {
    return failed(`Could not open ${model.name}`, [err instanceof Error ? err.message : String(err), ...result.output.split('\n').slice(-4)]);
  }

  // Staged here, opened there: the ordinary page takes over with the world,
  // and the isolation ends with the conversion.
  try {
    watch?.({ stage: 'staging' });
    const { staged, files: stagedFiles } = await stageBuilt(doc, built);
    const server = await ensureImportServer(win);
    await stashOpenedWorld(server.store, server.scopeUrl, { documentUrl: staged.documentUrl, title: built.title, modelName: model.name, lines: summarizeImport(built), files: stagedFiles });
  } catch (err) {
    return failed(`Could not open ${model.name}`, [err instanceof Error ? err.message : String(err)]);
  }
  // The window that opened this one shows the world; this one says it is ready (blendWindow.ts).
  if (leave !== null) return true;
  say(['Converted. Opening the world.']);
  win.location.replace(handBackUrl(win.location.href));
  return true;
}
