/**
 * What Blender wrote under /out, gathered into the converter's input: the
 * scene's glb, the report, and the files the report names by path (each
 * door's own glb, each speaker's sound, each picture of baked light, the
 * world's sky). The report's
 * paths are Blender's own file system's; the converter never sees them.
 */
import type { BlenderExport } from '@fivesqd/ingest/browser';

export const BLENDER_OUT_GLB = '/out/scene.glb';
export const BLENDER_OUT_REPORT = '/out/report.json';

type Report = BlenderExport['report'] & {
  portals?: Array<{ path: string }>;
  speakers?: Array<{ path: string }>;
  worldBackground?: { kind: string; path?: string } | null;
};

export function blenderOutputs(files: Readonly<Record<string, Uint8Array>>): BlenderExport & { portals: Uint8Array[]; speakers: Uint8Array[] } {
  const glb = files[BLENDER_OUT_GLB];
  if (!glb) throw new Error('Blender wrote no glb: the export did not finish. Its output is in the report above.');
  const reportBytes = files[BLENDER_OUT_REPORT];
  const report = (reportBytes ? JSON.parse(new TextDecoder().decode(reportBytes)) : {}) as Report;
  const byPath = (p: string | undefined): Uint8Array | undefined => (p ? files[p] : undefined);
  const portals = (report.portals ?? []).map((p) => byPath(p.path)).filter((b): b is Uint8Array => b !== undefined);
  const speakers = (report.speakers ?? []).map((s) => byPath(s.path)).filter((b): b is Uint8Array => b !== undefined);
  // One entry per picture the report lists, empty where Blender wrote none, so the order holds.
  const lightmaps = (report.lightmaps ?? []).map((m) => byPath(m.path) ?? new Uint8Array(0));
  const bg = report.worldBackground;
  const sky = bg && (bg.kind === 'panorama' || bg.kind === 'environment') ? byPath(bg.path) : undefined;
  return { glb, report: report as BlenderExport['report'], portals, speakers, lightmaps, sky };
}
